import { useEffect, useState } from 'react';
import { Link } from 'react-router-dom';
import { getPosts } from '../utils/storage';
import ReactMarkdown from 'react-markdown';
import AOS from 'aos';
import 'aos/dist/aos.css';
import './styles/Home.scss';

function Home() {
  const [posts, setPosts] = useState([]);
  const [search, setSearch] = useState('');
  const [selectedCategory, setSelectedCategory] = useState('all');
  const [currentPage, setCurrentPage] = useState(1);
  const postsPerPage = 5;

  useEffect(() => {
    AOS.init({ duration: 600, once: true });

    const stored = getPosts();
    const sorted = Array.isArray(stored)
      ? stored.sort((a, b) => new Date(b.createdAt) - new Date(a.createdAt))
      : [];
    setPosts(sorted);
  }, []);

  const categories = ['all', ...new Set(posts.map(p => p.category?.toLowerCase() || 'uncategorized'))];
  const tags = [...new Set(posts.flatMap(p => p.tags || []))];

  const filtered = posts.filter((post) => {
    const searchLower = search.toLowerCase();
    const matchesSearch =
      post.title.toLowerCase().includes(searchLower) ||
      post.content.toLowerCase().includes(searchLower) ||
      post.tags?.some(tag => tag.toLowerCase().includes(searchLower));

    const matchesCategory =
      selectedCategory === 'all' || post.category?.toLowerCase() === selectedCategory;

    return matchesSearch && matchesCategory;
  });

  const totalPages = Math.ceil((filtered.length - 1) / postsPerPage);
  const indexOfLast = currentPage * postsPerPage + 1;
  const indexOfFirst = indexOfLast - postsPerPage;
  const currentPosts = filtered.slice(1).slice(indexOfFirst - 1, indexOfLast - 1);
  const featuredPost = filtered[0];

  return (
    <div className="home container">
      <h1 className="home__heading">Blog Feed</h1>

      {/* ✅ Filters */}
      <div className="home__filters">
        <input
          type="text"
          className="home__search"
          placeholder="Search posts..."
          value={search}
          onChange={(e) => {
            setSearch(e.target.value);
            setCurrentPage(1);
          }}
        />

        <select
          className="home__select"
          value={selectedCategory}
          onChange={(e) => {
            setSelectedCategory(e.target.value);
            setCurrentPage(1);
          }}
        >
          {categories.map((cat) => (
            <option key={cat} value={cat}>
              {cat.toUpperCase()}
            </option>
          ))}
        </select>
      </div>

      {/* ✅ Layout Grid */}
      <div className="home__main-layout">
        <div className="home__left">
          {/* ✅ Featured Post */}
          {featuredPost && (
            <div className="home__featured" data-aos="fade-up">
              {featuredPost.image && (
                <img
                  src={featuredPost.image}
                  alt={featuredPost.title}
                  className="home__featured-image"
                />
              )}
              <div className="home__featured-body">
                <h2>{featuredPost.title}</h2>
                <ReactMarkdown>
                  {featuredPost.content.substring(0, 150) + '...'}
                </ReactMarkdown>
                <Link to={`/post/${featuredPost.id}`} className="home__read-link">
                  Read more →
                </Link>
              </div>
            </div>
          )}

          {/* ✅ Blog Grid */}
          <div className="home__grid">
            {currentPosts.map((post) => (
              <div key={post.id} className="home__card" data-aos="fade-up">
                {post.image && (
                  <img src={post.image} alt={post.title} className="home__card-image" />
                )}
                <div className="home__card-content">
                  <Link to={`/post/${post.id}`}>
                    <h3 className="home__card-title">{post.title}</h3>
                  </Link>
                  <ReactMarkdown>
                    {post.content.substring(0, 100) + '...'}
                  </ReactMarkdown>
                  <div className="home__card-meta">
                    <span className="home__card-category">{post.category}</span>
                    {post.tags?.length > 0 && (
                      <span className="home__card-tags">
                        {post.tags.map((tag, i) => (
                          <span key={i} className="home__card-tag">#{tag}</span>
                        ))}
                      </span>
                    )}
                  </div>
                </div>
              </div>
            ))}
          </div>

          {/* ✅ Pagination */}
          {totalPages > 1 && (
            <div className="home__pagination">
              {Array.from({ length: totalPages }, (_, i) => (
                <button
                  key={i}
                  className={`home__page-btn ${currentPage === i + 1 ? 'active' : ''}`}
                  onClick={() => setCurrentPage(i + 1)}
                >
                  {i + 1}
                </button>
              ))}
            </div>
          )}
        </div>

        {/* ✅ Sidebar */}
        <aside className="home__sidebar" data-aos="fade-left">
          <h4>Trending Tags</h4>
          <div className="home__sidebar-tags">
            {tags.length === 0 ? (
              <p>No tags found.</p>
            ) : (
              tags.map((tag, i) => (
                <span key={i} className="home__sidebar-tag">#{tag}</span>
              ))
            )}
          </div>

          <h4>Categories</h4>
          <ul className="home__sidebar-categories">
            {categories.filter(c => c !== 'all').map((cat, i) => (
              <li key={i}>{cat}</li>
            ))}
          </ul>
        </aside>
      </div>
    </div>
  );
}

export default Home;
